for prog in [0,9,40,41,42,44,45,46,47,48,56,57,58,60,68,70,71,73]:
 for pitch in [52,64,71,83]:
  for vel in [40,65,85,110]:
   y=s.render(prog,pitch,vel=vel);f,tt,z=stft(y,22050,nperseg=4096,noverlap=3876);q=gaussian_filter1d(np.mean(abs(z[:,(tt>.1)&(tt<1)]),1)*w,.7);n=np.linalg.norm(q);res.append((float(r@q/max(n,1e-8)),prog,pitch,vel))
print(sorted(res,reverse=True)[:35]);s.close()\""

/bin/bash -lc "python - <<'PY'
import mido,json,xml.etree.ElementTree as E,collections
s=E.parse('complete_score_styled.mscx').getroot().find('Score')
parts=s.findall('Part'); expected=json.load(open('score_events.json'));f=mido.MidiFile('review.mid');tracks={}
for i,p in enumerate(parts):
 notes=[]
 for staff in p.findall('Staff'):
  tr=f.tracks[int(staff.get('id'))-1];q=0
  for msg in tr:
   q+=msg.time/f.ticks_per_beat
   if msg.type=='note_on' and msg.velocity>0:notes.append((msg.note,round(q,4)))
 ex=[(e['pitch'],e['onset']) for e in expected if e['part']==i]
 miss=[n for n in ex if n not in notes];extra=[n for n in notes if n not in ex]
 print(i,p.findtext('trackName'),'expected',len(ex),'midi',len(notes),'missing',miss[:8],'extra',extra[:8])
PY"

